#include <stdio.h>

enum Status { PENDING, ACTIVE, CLOSED };

typedef struct {
    int x, y;
} Point;

typedef enum { LOW, MEDIUM, HIGH } Priority;

int main() {
    enum Status s = ACTIVE;
    printf("%d\n", s);           // 1

    Point p = {3, 4};             // no 'struct' keyword needed, thanks to typedef
    printf("(%d, %d)\n", p.x, p.y);

    Priority level = HIGH;
    printf("%d\n", level);        // 2
    return 0;
}
